@router.get('/api/exports/{export_id}/stream')
async def stream_export_archive(
    export_id: str,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    export = db.query(ExportJob).filter(ExportJob.export_id == export_id, ExportJob.user_id == current_user.id).first()
    if not export or not os.path.exists(export.file_path):
        raise HTTPException(status_code=404, detail="Export file ready for download not found")

    async def iterfile():
        async with aiofiles.open(export.file_path, mode="rb") as f:
            while chunk := await f.read(65536):
                yield chunk

    return StreamingResponse(iterfile(), media_type="application/gzip")
